01-rule-for-a-good.cypher:
// Which origin rule applies to a good under an agreement.
// An exact subheading rule wins over a range, a range over a heading, a
// heading over a chapter; the normalised interval makes all four comparable.
MATCH (r:OriginRule {agreement: $agreement})
WHERE r.from_norm <= $norm AND r.to_norm >= $norm
RETURN r.id AS rule, r.level AS level, r.code_from AS from_code, r.code_to AS to_code,
       r.text AS text, r.priority AS priority
ORDER BY r.priority ASC, r.to_norm ASC
LIMIT 1;

02-exclusion-interval.cypher:
// Does a material sit inside a provision the rule excludes?
//
// $material_norm is the material's code normalised to the eight digit space the
// rules use, so a fully classified material is one comparison against the
// interval the rule row carries.  `inside_group` is the answer for that code.
//
// This is the single material form of the join the engine actually runs
// (cypher/07-material-against-rule.cypher): the intervals a rule names are
// nodes it points at, and the material list meets them in one traversal.  That
// form sends the span a coarse code can name, so heading 8504 goes in as
// 85040000 to 85049999 and comes back "across" 8504.10 to 8504.50, which is the
// third answer this single comparison cannot show.  This file is kept as the
// one line version a reader can paste when the code is fully classified.
MATCH (r:OriginRule {id: $rule})
WITH r, $material_norm AS material
RETURN material >= r.group_exclude_from AND material <= r.group_exclude_to AS inside_group,
       r.group_exclude_from AS from_code, r.group_exclude_to AS to_code;

03-rate-on-a-date.cypher:
// The rate row for a line, with the staging it is subject to.
// The date arithmetic lives in the engine because each annex says it in a
// sentence, not a column; this returns the row that sentence applies to.
// Japan's row carries the printed schedule in `years`, so the cell for the
// year in question is read straight out of the row.
// A schedule can carry more than one row for one line: Japan prints a general
// rate and, on some lines, a treatment for Korea or for other parties.  A Korean
// shipment is priced on the Korea row when there is one, else on the general
// row, and never on a row written for another party.
MATCH (r:RateLine {code: $code, market: $market, agreement: $agreement})
WHERE coalesce(r.partner, 'ALL') IN ['KR', 'ALL']
MATCH (r)-[:CITED_FROM]->(src:Source)
RETURN r.base_rate_percent AS base_rate, r.base_rate_text AS rate_text,
       r.staging AS staging, r.years AS printed_years, r.partner AS partner,
       src.id AS source, toString(src.as_of) AS source_as_of
ORDER BY CASE WHEN r.partner = 'KR' THEN 0 ELSE 1 END
LIMIT 1;

04-hierarchy-above-a-good.cypher:
// The supply chain of a good: every heading and chapter above it.
MATCH (s:Subheading {code: $subheading})-[:IN_HEADING]->(h:Heading)-[:IN_CHAPTER]->(c:Chapter)
RETURN s.code AS subheading, s.title AS subheading_title, h.code AS heading,
       h.title AS heading_title, c.code AS chapter, c.title AS chapter_title;

05-coverage-by-agreement.cypher:
// What the snapshot can answer, per agreement, before anyone asks it.
MATCH (a:Agreement)
OPTIONAL MATCH (r:OriginRule)-[:FOR]->(a)
OPTIONAL MATCH (t:RateLine)-[:FOR]->(a)
RETURN a.code AS agreement, a.market AS market, a.coverage AS coverage,
       count(DISTINCT r) AS rules, count(DISTINCT t) AS rate_lines;

06-market-comparison.cypher:
// One good, three markets: the rule that applies and the line that prices it,
// for every agreement the snapshot covers, in one traversal.
//
// $codes is a map of market to the good's tariff line in that market's
// nomenclature, exactly as a shipment states it:
//   {US: '85044095', EU: '85044090', JP: '850440090'}
// $norms is the same code normalised to the eight digit space the rules use.
//
// A code can sit inside more than one rule interval (a heading and a chapter
// rule both cover 8504.40), so the rules are ordered the way the engine orders
// them, most specific first, and the first one is the rule that applies.
MATCH (a:Agreement)
WHERE a.coverage <> 'none' AND a.code <> 'MFN'
OPTIONAL MATCH (rule:OriginRule)-[:FOR]->(a)
  WHERE rule.from_norm <= $norms[a.market] AND rule.to_norm >= $norms[a.market]
WITH a, rule
ORDER BY a.code, rule.priority ASC, rule.to_norm ASC
WITH a, collect(rule)[0] AS rule
OPTIONAL MATCH (rule)-[:CITED_FROM]->(rule_source:Source)
OPTIONAL MATCH (rate:RateLine)-[:FOR]->(a)
  WHERE rate.code = $codes[a.market] AND rate.market = a.market
    AND coalesce(rate.partner, 'ALL') IN ['KR', 'ALL']
RETURN a.code AS agreement, a.market AS market, a.approved_exporter_required AS needs_approval,
       rule.code_from AS rule_from, rule.text AS rule_text, rule_source.id AS rule_source,
       rate.code AS line, rate.base_rate_percent AS base_rate, rate.staging AS staging,
       rate.years AS printed_years
ORDER BY a.code;

07-material-against-rule.cypher:
// Which materials sit inside a provision the rule excludes?
//
// $materials is the bill of materials as codes, one entry per material:
//   [{id: 'M1', start_norm: '85041000', end_norm: '85049999'}, ...]
// $rule is the OriginRule id and $alternative is which alternative of its
// sentence the intervals belong to (the sentence can say "or").
//
// The provisions are HsInterval nodes hanging off the rule, one per excluded
// token, one per excluded range and one for the group the rule excludes, each
// with the eight digit bounds the comparison runs on.  The join returns one row
// per material and interval that are not disjoint, with the relation the engine
// uses:
//
//   inside   every line the material can name is in the interval
//   across   the material is written too coarsely, so the interval cuts it and
//            the exporter has not said enough (an honest "cannot tell")
//   outside  none of the lines is in the interval, and that pair is dropped
//
// A material is sent as the interval it can name, so heading 8504 goes in as
// 85040000 to 85049999 and comes back "across" 8504.10 to 8504.50 rather than
// passing as the top line of its own heading.  No material is written to the
// store: the list arrives as a parameter and leaves with the answer.
UNWIND $materials AS m
MATCH (r:OriginRule {id: $rule})-[:EXCLUDES]->(i:HsInterval)
WHERE i.alternative = $alternative
WITH m, i,
  CASE WHEN m.end_norm < i.from_norm OR m.start_norm > i.to_norm THEN 'outside'
       WHEN m.start_norm >= i.from_norm AND m.end_norm <= i.to_norm THEN 'inside'
       ELSE 'across' END AS relation
WHERE relation <> 'outside'
RETURN m.id AS material, i.kind AS kind, i.ord AS ord, i.label AS label,
       i.low AS low_code, i.high AS high_code, relation AS relation
ORDER BY m.id, i.kind, i.ord;

08-rule-attachment.cypher:
// The rule that applies to a good, the intervals it excludes and the document
// it is cited to, in one walk of the graph.
//
// $agreement is the agreement code (KORUS, EUKOR, RCEP) and $norm is the good's
// code normalised to the eight digit space the rules use.  One row comes back
// per interval the rule names, with the rule and source columns repeated; a
// rule that names no interval comes back once with the interval columns null.
//
// This is the query the demo's own picture reads: every node it draws to the
// right of the bill of materials is a row of this statement or of
// cypher/09, so the picture cannot show a rule the snapshot does not hold.
MATCH (a:Agreement {code: $agreement})
OPTIONAL MATCH (rule:OriginRule)-[:FOR]->(a)
  WHERE rule.from_norm <= $norm AND rule.to_norm >= $norm
WITH a, rule
ORDER BY rule.priority ASC, rule.to_norm ASC
WITH a, collect(rule)[0] AS rule
OPTIONAL MATCH (rule)-[:EXCLUDES]->(i:HsInterval)
OPTIONAL MATCH (rule)-[:CITED_FROM]->(source:Source)
RETURN rule.id AS rule_id, rule.kinds AS kinds, rule.level AS level,
       rule.code_from AS code_from, rule.code_to AS code_to, rule.text AS text,
       rule.group_exclude_from AS group_from, rule.group_exclude_to AS group_to,
       rule.rvc_build_down AS rvc_down, rule.rvc_build_up AS rvc_up,
       rule.originating_weight_min AS weight_min, rule.structured AS structured,
       rule.priority AS priority,
       i.id AS interval_id, i.alternative AS interval_alternative,
       i.kind AS interval_kind, i.ord AS interval_ord, i.label AS interval_label,
       i.low AS interval_low, i.high AS interval_high,
       i.from_norm AS interval_from, i.to_norm AS interval_to,
       source.id AS source_id, source.title AS source_title
ORDER BY interval_alternative, interval_kind, interval_ord;

09-classification-spine.cypher:
// Where a stated code sits in the classification the snapshot holds: its
// subheading, the heading above it and the chapter above that.
//
// $rows is a list of {code, role, sub6, heading} objects, where code is the
// code as the exporter stated it, role is the caller's own label for the line
// (the good, or a material), and sub6 and heading are the two prefixes of that
// code.  The node is looked up by its key, so a code whose subheading or
// heading is not in the snapshot comes back with nulls rather than a guess.
//
// The edges the picture draws from the subheading up are the two the graph
// holds, IN_HEADING and IN_CHAPTER; nothing here invents a level the snapshot
// does not carry.
UNWIND $rows AS row
OPTIONAL MATCH (s:Subheading {code: row.sub6})
OPTIONAL MATCH (h:Heading {code: row.heading})
OPTIONAL MATCH (h)-[:IN_CHAPTER]->(c:Chapter)
RETURN row.code AS code, row.role AS role, row.label AS label,
       s.code AS subheading, h.code AS heading, c.code AS chapter
ORDER BY role, code;
